steps.script:
var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.setup(2, {"cp": {"1": 0}})

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
PhaseManager.transition_to_phase(8)
return int(GameState.get_current_phase())

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.frame(7, 40, 1.2)

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.shoot("U_GRETCHIN_C", "U_WULFEN_A")

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.decline_others(2) >= 0

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.window_id()

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.decider()

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return "U_WULFEN_A" in H.phase().get_pending_stratagem_window().get("ctx", {}).get("targeted_unit_ids", [])

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return main.get_tree().root.get_node("Ork11eReactiveMovePanel/Content/Header").text.begins_with("IMPETUOSITY — Wulfen")

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
var info = H.phase().ork11e_reactive_move_info()
Engine.set_meta("sw11e_imp_d0", H.common().group_distance_inches("U_WULFEN_A", "U_GRETCHIN_C"))
return info.kind == "surge" and int(info.roll) >= 1 and int(info.roll) <= 6 and float(info.max_inches) == float(info.roll) and info.surge_target == "U_GRETCHIN_C"

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
var info = H.phase().ork11e_reactive_move_info()
return bool(info.valid) and float(info.moved_inches) > 0.0 and float(info.moved_inches) <= float(info.max_inches) + 0.05

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.phase()._ork11e_followup.is_empty() and not H.phase().has_pending_stratagem_window()

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.log_count("IMPETUOSITY")

var main = tree.current_scene
var H = load("res://tests/helpers/sw11e_s3_scen.gd")
return H.common().group_distance_inches("U_WULFEN_A", "U_GRETCHIN_C") < float(Engine.get_meta("sw11e_imp_d0", 99.0))
